  "COMEÇO": "START",
  "Você escolhe 3 lutadores. Eles lutam sozinhos: seu trabalho é montar um trio que funcione junto.": "You pick 3 fighters. They fight on their own: your job is to build a trio that works together.",
  "Jornada": "Journey",
  "OBJETIVO": "GOAL",
  "10 lutas seguidas. Cada luta soma pontos pelo que o trio fez: dano, nocautes, cura e proteção, habilidades, Status, ritmo, Carga e manter o trio vivo — com o peso certo para cada personagem, para todo estilo de jogo pontuar parecido. A vitória vale 25 mil a mais. Uma derrota encerra a jornada, mas os pontos dela ficam.": "10 fights in a row. Each fight adds points for what the trio did: damage, knockouts, healing and protection, skills, Status, pace, Charge and keeping the trio alive — weighted for each character, so every play style scores about the same. A win is worth 25K more. A loss ends the journey, but its points stay.",
  "SOBREVIVER": "SURVIVE",
  "Quando chega a zero, o lutador sai da luta. A Vida que sobra no fim vale pontos.": "When it hits zero, the fighter leaves the fight. The Health left at the end is worth points.",
  "RITMO": "PACE",
  "O golpe de sempre, com o nome e o jeito de cada lutador: uns quicam no segundo rival, uns pegam dois, uns curam o aliado, roubam Carga ou fecham um combo no 3º golpe. O círculo em volta do retrato mostra quanto falta para o próximo.": "The everyday hit, with each fighter's own name and style: some bounce to a second rival, some hit two, some heal an ally, steal Charge or finish a combo on the 3rd hit. The circle around the portrait shows how long until the next one.",
  "Vantagem": "Advantage",
  "QUEM DOMINA": "WHO'S AHEAD",
  "A barra do topo mostra quem está controlando a luta. Algumas habilidades reagem a ela; virar o jogo dá pontos.": "The bar at the top shows who is controlling the fight. Some skills react to it; turning the fight around gives points.",
  "Investigação": "Investigation",
  "ESTUDAR O RIVAL": "STUDY THE RIVAL",
  "Alguns lutadores estudam um rival por vez. Ao chegar a 100, abrem uma habilidade que só funciona contra quem foi estudado.": "Some fighters study one rival at a time. When it reaches 100, they unlock a skill that only works against the one they studied.",
  "DECISÕES": "DECISIONS",
  "De 0 a 100: quanto melhor, mais o lutador escolhe o alvo e a hora certa sozinho.": "From 0 to 100: the higher it is, the better the fighter picks the right target and the right moment on their own.",
