  "Irmãos Kamado": "Kamado siblings",
  "Parceiros de missão": "Mission partners",
  "Irmãos Shotokan": "Shotokan brothers",
  "Hora de Aventura!": "Adventure Time!",
  "Dupla Dinâmica": "Dynamic Duo",
  "Irmãos Mario": "Mario Bros.",
  "Bando do Chapéu de Palha": "Straw Hat Crew",
  "Kira e L": "Kira and L",
  "Rick e Morty": "Rick and Morty",
  "Família Griffin": "The Griffins",
  "Herdeiros do fogo": "Heirs of fire",
  "Shadow Moses": "Shadow Moses",
  "quem recebe atrasa em 1 s o Preparo do rival que estiver preparando": "the receiver delays the Wind-up of the rival winding up by 1 s",
  "quem recebe ganha 12 de Carga nas habilidades": "the receiver gains 12 Charge on their skills",
  "quem recebe põe uma Bomba de 80 no rival mais forte (explode em 3 s)": "the receiver puts an 80 Bomb on the strongest rival (explodes in 3 s)",
  "quem recebe guarda 40 de energia para soltar depois": "the receiver stores 40 energy to release later",
  "quem recebe ganha Espinhos: quem bater nele leva 20 de dano por golpe, por 4 s": "the receiver gains Thorns: attackers take 20 damage per hit, for 4 s",
  "quem recebe Provoca todos os rivais de novo por 2,5 s": "the receiver Taunts all rivals again for 2.5 s",
  "quem recebe ganha Regeneração: +12 de Vida por segundo, por 4 s": "the receiver gains Regeneration: +12 Health per second, for 4 s",
  "quem recebe tira 1 Status ruim de si": "the receiver removes 1 bad Status from themselves",
  "quem recebe Envenena todos os rivais: −6 de Vida por segundo, por 5 s": "the receiver Poisons all rivals: −6 Health per second, for 5 s",
  "quem recebe deixa o rival mais forte Lento (25% mais devagar) por 6 s": "the receiver Slows the strongest rival (25% slower) for 6 s",
  "o trio todo fica Protegido (recebe 12% menos dano) por 5 s": "the whole trio is Protected (takes 12% less damage) for 5 s",
  "quem recebe cura 60 de Vida no aliado mais ferido": "the receiver heals the most injured ally for 60 Health",
  "quem recebe fica Acelerado (15% mais rápido) por 4 s": "the receiver is Hasted (15% faster) for 4 s",
  "quem recebe deixa o rival mais fraco Queimando: −10 de Vida por segundo, por 4 s": "the receiver sets the weakest rival Burning: −10 Health per second, for 4 s",
  "quem recebe deixa o rival mais forte Exposto (recebe 15% mais dano) por 5 s": "the receiver Exposes the strongest rival (takes 15% more damage) for 5 s",
  "quem recebe tira 1 buff do rival mais forte": "the receiver removes 1 buff from the strongest rival",
  "quem recebe ganha Escudo de 80": "the receiver gains an 80 Shield",
  "quem recebe ganha Regeneração: +15 de Vida por segundo, por 4 s": "the receiver gains Regeneration: +15 Health per second, for 4 s",
  "todos os rivais ficam Lentos (15% mais devagar) por 4 s": "all rivals are Slowed (15% slower) for 4 s",
  "o trio todo fica Protegido (recebe 15% menos dano) por 4 s": "the whole trio is Protected (takes 15% less damage) for 4 s",
  "uma armadilha deixa o rival mais forte Confuso (pode errar e se acertar) por 4 s": "a trap Confuses the strongest rival (may miss and hit themselves) for 4 s",
  "Dante entra em Devil Trigger: fica Fortalecido (+15% de dano) por 6 s": "Dante enters Devil Trigger: Empowered (+15% damage) for 6 s",
  "Nezuko dá Escudo de 70 ao aliado mais ferido": "Nezuko gives a 70 Shield to the most injured ally",
  "L expõe o rival mais forte (recebe 15% mais dano) por 5 s": "L exposes the strongest rival (takes 15% more damage) for 5 s",
  "Azula deixa o rival mais fraco Queimando: −10 de Vida por segundo, por 4 s": "Azula sets the weakest rival Burning: −10 Health per second, for 4 s",
  "Congela um rival": "freezes a rival",
  "deixa um rival Queimando": "sets a rival Burning",
  "Envenena um rival": "poisons a rival",
  "faz um rival Sangrar": "makes a rival Bleed",
  "faz um rival Dormir": "puts a rival to Sleep",
  "deixa um rival Cego": "Blinds a rival",
  "deixa um rival Eletrizado": "Electrifies a rival",
  "põe uma Bomba num rival": "puts a Bomb on a rival",
  "deixa um rival Amaldiçoado": "Curses a rival",
  "deixa um rival Marcado": "Marks a rival",
  "Provoca os rivais (eles só batem nele)": "Taunts the rivals (they only hit them)",
  "Paralisa, Congela ou faz Dormir um rival por 1,5 s ou mais": "Paralyzes, Freezes or puts a rival to Sleep for 1.5 s or more",
  "Silencia todos os rivais de uma vez": "Silences all rivals at once",
  "deixa todos os rivais Expostos de uma vez": "Exposes all rivals at once",
  "deixa todos os rivais Confusos de uma vez": "Confuses all rivals at once",
  "deixa todos os rivais Lentos de uma vez": "Slows all rivals at once",
  "Paralisa todos os rivais de uma vez": "Paralyzes all rivals at once",
  "Enraíza todos os rivais de uma vez": "Roots all rivals at once",
  "copia a habilidade de um rival": "copies a rival's skill",
  "enche a Carga de um aliado": "fills an ally's Charge",
  "cura um aliado": "heals an ally",
  "revive um aliado caído": "revives a fallen ally",
  "tira os Status ruins dos aliados": "removes allies' bad Status",
  "dá Barreira aos aliados": "gives allies Barrier",
  "dá Regeneração aos aliados": "gives allies Regeneration",
  "deixa os aliados Fortalecidos": "Empowers allies",
  "deixa os aliados Acelerados": "Hastes allies",
  "adianta a vez dos aliados": "speeds up allies' turns",
  "dá Escudo a um aliado": "gives an ally a Shield",
  "tira os buffs dos rivais (Dissipar)": "removes rivals' buffs (Dispel)",
  "invoca uma criatura": "summons a creature",
  "tem uma habilidade que tira 500 de dano ou mais": "has a skill that deals 500 damage or more",
  "tem uma habilidade que tira 550 de dano ou mais": "has a skill that deals 550 damage or more",
  "tem uma habilidade que tira 600 de dano ou mais": "has a skill that deals 600 damage or more",
  "acerta todos os rivais de uma vez com 350 de dano ou mais": "hits all rivals at once for 350 damage or more",
  "tem uma habilidade com Preparo de 3 s ou mais": "has a skill with a Wind-up of 3 s or more",
  "tem 900 de Vida ou menos": "has 900 Health or less",
  "tem 1400 de Vida ou mais": "has 1400 Health or more",
  "tem Vampirismo ou rouba Vida": "has Lifesteal or drains Health",
  "tem Espinhos ou Refletir": "has Thorns or Reflect",
  "ganha Esquiva": "gains Dodge",
