  "tem um Traço que dispara quando um rival se machuca": "has a Trait that triggers when a rival gets hurt",
  "Sem Baixas": "No Losses",
  "Vença as lutas 1, 2 e 3 terminando cada uma com os três do trio de pé.": "Win fights 1, 2 and 3, finishing each with all three of the trio standing.",
  "Três lutas, três de pé. Ninguém fica pelo caminho.": "Three fights, three standing. Nobody gets left behind.",
  "Clássico do Universo": "Universe Classic",
  "Monte o trio com três personagens do mesmo universo e vença as 5 primeiras lutas. A luta extra é contra outros do mesmo universo.": "Build the trio with three characters from the same universe and win the first 5 fights. The extra fight is against others from that universe.",
  "Quem vem do mesmo mundo luta melhor junto… e atrai velhos conhecidos.": "Those from the same world fight better together… and attract old acquaintances.",
  "Trio Intacto": "Intact Trio",
  "Vença a luta 10 com os três do trio de pé.": "Win fight 10 with all three of the trio standing.",
  "Chegar ao fim é bom. Chegar inteiro é lenda.": "Reaching the end is good. Reaching it whole is legendary.",
  "A Virada": "The Comeback",
  "Em qualquer luta, fique com só um do trio de pé contra os três rivais e vença assim mesmo. Depois, vença as 10.": "In any fight, be down to one of the trio against all three rivals and win anyway. Then, win all 10.",
  "Sozinho contra três. Quem não desiste…": "Alone against three. Whoever doesn't give up…",
