  "Copia você": "Copies you",
  "Olha os seus 3 times e monta os dele com personagens que fazem as mesmas coisas, só que escolhidos a dedo. E já testa as lutas antes de escolher o time.": "Looks at your 3 teams and builds his with characters that do the same things, only hand-picked. And he tests the fights before picking a team.",
