  "Vê o Futuro": "Sees the Future",
  "Vidente": "Seer",
  "Monta com trios fortes e, de vez em quando, vê o futuro: testa lutas de cada time dele contra cada time seu antes de escolher.": "Builds with strong trios and, now and then, sees the future: tests fights of each of his teams against each of yours before picking.",
