  "A motosserra não para de girar.": "The chainsaw never stops spinning.",
  "As correntes do inferno prendem todos.": "The chains of hell bind everyone.",
  "Sete dias: a maldição sempre chega.": "Seven days: the curse always arrives.",
  "O demônio freira: amaldiçoa e confunde.": "The demon nun: curses and confuses.",
  "O senhor dos vampiros: morcegos e sede de sangue.": "The lord of vampires: bats and bloodthirst.",
  "Sangue ácido e uma emboscada que vem do teto.": "Acid blood and an ambush that comes from the ceiling.",
  "Camuflagem, mira laser e um troféu no fim.": "Camouflage, laser sight and a trophy at the end.",
  "O lado sombrio: esgana com a Força e corta com o sabre.": "The dark side: chokes with the Force and cuts with the saber.",
