  "Se a situação não aparecer, ele faz pouco.": "If the situation doesn't come up, they do little.",
  "Chama uma criatura que ataca o rival mais ferido a cada 1,5 s.": "Calls a creature that attacks the most injured rival every 1.5 s.",
  "Ela continua atacando mesmo com quem invocou travado.": "It keeps attacking even while the summoner is locked down.",
  "Dissipar manda a criatura embora, e ela some se quem invocou cair.": "Dispel sends the creature away, and it disappears if the summoner falls.",
