  "Só tira o que já está lá: contra rivais que não põem debuff, vale pouco.": "Only removes what's already there: against rivals who don't apply debuffs, it's worth little.",
  "Tira os buffs dos rivais, os que mais ajudam primeiro: Protegido, Refletir, Vampirismo, Fortalecido…": "Removes the rivals' buffs, the most helpful first: Protected, Reflect, Lifesteal, Empowered…",
